parameters.jsCode:
try {
  const cotizaciones = await this.helpers.httpRequest({
    url: 'https://api.argentinadatos.com/v1/cotizaciones/dolares/oficial',
    method: 'GET',
    json: true
  });

  if (!Array.isArray(cotizaciones) || cotizaciones.length === 0) {
    return JSON.stringify({
      estado: "ERROR",
      mensaje: "La API de ArgentinaDatos no devolvió cotizaciones. Avisar al usuario antes de calcular el cierre."
    });
  }

  const fechaObjetivo = (query.periodo || "").toString();

  const cierresPorMes = {};
  for (const item of cotizaciones) {
    if (!item.fecha || item.compra === undefined || item.venta === undefined) continue;
    const periodo = item.fecha.substring(0, 7); // AAAA-MM
    cierresPorMes[periodo] = {
      periodo: periodo,
      fecha_cierre_habil: item.fecha,
      compra: item.compra,
      venta: item.venta
    };
  }

  const periodoBuscado = fechaObjetivo.substring(0, 7);

  if (periodoBuscado && cierresPorMes[periodoBuscado]) {
    return JSON.stringify({
      estado: "OK",
      mensaje: `Cotización del último día hábil para el mes ${periodoBuscado}`,
      cotizacion_aplicable: cierresPorMes[periodoBuscado]
    });
  }

  const periodosDisponibles = Object.keys(cierresPorMes).sort();
  const ultimoPeriodo = periodosDisponibles[periodosDisponibles.length - 1];

  return JSON.stringify({
    estado: "ULTIMO_DISPONIBLE",
    mensaje: `No se encontró cotización exacta para ${fechaObjetivo}. Se utiliza la cotización del último día hábil registrado en el sistema (${cierresPorMes[ultimoPeriodo].fecha_cierre_habil}).`,
    cotizacion_aplicable: cierresPorMes[ultimoPeriodo]
  });

} catch (error) {
  return JSON.stringify({
    estado: "ERROR",
    mensaje: `Falló la consulta a ArgentinaDatos: ${error.message}`
  });
}

